from collections import deque

class Queue:
    def __init__(self):
        self._deque = deque()

    def enqueue(self, val):
        self._deque.append(val)

    def dequeue(self):
        if not self._deque:
            raise IndexError('Очередь пуста')
        return self._deque.popleft()

    def is_empty(self) -> bool:
        return len(self._deque) == 0

    def __len__(self):
        return len(self._deque)

