def are_connected(graph: dict, src, dst) -> bool:
    visited = set()
    stack = [src]
    while stack:
        node = stack.pop()
        if node == dst:
            return True
        if node not in visited:
            visited.add(node)
            stack.extend(graph.get(node, []))
    return False

