def update_product_stock(conn, product_id, qty):
    with conn.cursor() as cur:
        cur.execute(
            'SELECT stock, version FROM products WHERE id = %s',
            (product_id,)
        )
        row = cur.fetchone()
        if not row:
            raise ValueError('Товар не найден')
        stock, version = row
        if stock < qty:
            raise ValueError('Недостаточно товара')
        cur.execute(
            'UPDATE products '
            'SET stock = stock - %s, version = version + 1 '
            'WHERE id = %s AND version = %s',
            (qty, product_id, version)
        )
        if cur.rowcount == 0:
            raise RuntimeError('Конфликт оптимистической блокировки')

