# Вычисление выражения в обратной польской нотации (RPN)
def eval_rpn(tokens: list) -> int:
    stack = []
    ops = {
        '+': lambda a, b: a + b,
        '-': lambda a, b: a - b,
        '*': lambda a, b: a * b,
        '/': lambda a, b: int(a / b)
    }
    for token in tokens:
        if token in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[token](a, b))
        else:
            stack.append(int(token))
    return stack[0]

# Проверка валидности BST
def is_valid_bst(root: TreeNode) -> bool:
    def validate(node, low, high):
        if not node:
            return True
        if not (low < node.val < high):
            return False
        left_ok = validate(
            node.left, low, node.val
        )
        right_ok = validate(
            node.right, node.val, high
        )
        return left_ok and right_ok
    inf = float('inf')
    return validate(root, -inf, inf)

