# Вставка узла в BST
def insert_into_bst(
    root: TreeNode, val: int
) -> TreeNode:
    if not root:
        return TreeNode(val)
    if val < root.val:
        root.left = insert_into_bst(
            root.left, val
        )
    else:
        root.right = insert_into_bst(
            root.right, val
        )
    return root

