# Постройте структуру для поиска медианы в потоке чисел
import heapq

class MedianFinder:
    def __init__(self):
        self.small = []  # max-heap (инвертированные значения)
        self.large = []  # min-heap

    def add_num(self, num: int):
        heapq.heappush(self.small, -num)
        heapq.heappush(self.large, -heapq.heappop(self.small))
        if len(self.large) > len(self.small):
            heapq.heappush(self.small, -heapq.heappop(self.large))

    def find_median(self) -> float:
        if len(self.small) > len(self.large):
            return float(-self.small[0])
        return (-self.small[0] + self.large[0]) / 2.0

# Напишите парсер raw HTTP-запроса из байтового потока
def parse_raw_http(raw_bytes: bytes) -> dict:
    headers_part, _, body = raw_bytes.partition(b"\r\n\r\n")
    lines = headers_part.decode("latin1").split("\r\n")
    method, path, version = lines[0].split(" ", 2)
    headers = {}
    for line in lines[1:]:
        if ":" in line:
            k, v = line.split(":", 1)
            headers[k.strip().lower()] = v.strip()
    return {"method": method, "path": path, "version": version, "headers": headers, "body": body}

