solution:
# Напишите фикстуру pytest с setup и teardown через yield
import pytest

class FakeDBConnection:
    def __init__(self):
        self.closed = False
        self.in_tx = True

    def rollback(self):
        self.in_tx = False

    def close(self):
        self.closed = True

@pytest.fixture
def db_conn():
    # Setup: подготовка соединения перед тестом
    conn = FakeDBConnection()
    yield conn
    # Teardown: гарантированная очистка после завершения теста
    conn.rollback()
    conn.close()

def test_connection_active_during_test(db_conn):
    assert db_conn.closed is False
    assert db_conn.in_tx is True

