pair2 = auth.refresh_tokens(pair1["refresh"])
print("Новая пара выдана для user_id:", pair2["access"]["sub"])
try:
    auth.refresh_tokens(pair1["refresh"])
    assert False, "Повторное использование старого refresh-токена должно блокироваться"
except PermissionError as e:
    print("Повторный вызов перехвачен:", e)

