    def __call__(self, environ, start_response):
        start_time = time.perf_counter()

        def custom_start_response(status, response_headers, exc_info=None):
            duration = time.perf_counter() - start_time
            headers = list(response_headers)
            headers.append(('X-Process-Time', f'{duration:.4f}s'))
            return start_response(status, headers, exc_info)

        return self.app(environ, custom_start_response)

captured = {}
def mock_start_response(status, headers, exc_info=None):
    captured['status'] = status
    captured['headers'] = dict(headers)
    return lambda data: None

def simple_app(environ, start_response):
    start_response('200 OK', [('Content-Type', 'text/plain')])
    return [b'Hello WSGI']

if __name__ == '__main__':
    middleware = TimingMiddleware(simple_app)
    result = middleware({}, mock_start_response)
    print('Статус:', captured.get('status'))
    print('Заголовки:', captured.get('headers'))

# Реализуйте ASGI-приложение с нуля с обработкой lifespan и HTTP-маршрутизацией
import asyncio
import json

app_state = {"db_connected": False}

async def asgi_app(scope: dict, receive, send):
    if scope["type"] == "lifespan":
        msg = await receive()
        if msg["type"] == "lifespan.startup":
            app_state["db_connected"] = True
            await send({"type": "lifespan.startup.complete"})
    elif scope["type"] == "http":
        payload = json.dumps({"path": scope["path"], "db": app_state["db_connected"]}).encode()
        await send({
            "type": "http.response.start",
            "status": 200,
            "headers": [(b"content-type", b"application/json")],
        })
        await send({"type": "http.response.body", "body": payload})

async def main():
    sent_events = []
    async def mock_send(event):
        sent_events.append(event)
    async def recv_startup():
        return {"type": "lifespan.startup"}
    await asgi_app({"type": "lifespan"}, recv_startup, mock_send)
    async def recv_http():
        return {"type": "http.request"}
    await asgi_app({"type": "http", "path": "/ping"}, recv_http, mock_send)
    body = json.loads(sent_events[-1]["body"].decode())
    print("ASGI Ответ:", body)
    assert body == {"path": "/ping", "db": True}

if __name__ == "__main__":
    asyncio.run(main())

import hashlib

def hash_git_blob(data: bytes) -> str:
    header = f'blob {len(data)}\0'.encode('ascii')
    store = header + data
    return hashlib.sha1(store).hexdigest()

