    pass

solution:
def git_bisect_find(
    commits: list[str],
    test_fn: callable
) -> str:
    left = 0
    right = len(commits) - 1
    while left + 1 < right:
        mid = (left + right) // 2
        if test_fn(commits[mid]):
            left = mid
        else:
            right = mid
    return commits[right]

def detect_merge_conflicts(
    base: dict[str, str],
    ours: dict[str, str],
    theirs: dict[str, str]
) -> list[str]:
    conflicts = []
    all_files = (
        set(base) | set(ours) | set(theirs)
    )
    for f in all_files:
        b_val = base.get(f)
        o_val = ours.get(f)
        t_val = theirs.get(f)
        if (
            o_val != b_val
            and t_val != b_val
            and o_val != t_val
        ):
            conflicts.append(f)
    return sorted(conflicts)

tests:
assert 'detect_merge_conflicts' in globals() and callable(detect_merge_conflicts)

# 1. Базовый сценарий: f1 конфликт, f2 только ours, f3 только theirs
base = {'f1': 'v1', 'f2': 'v2', 'f3': 'v3'}
ours = {'f1': 'v1_ours', 'f2': 'v2_new', 'f3': 'v3'}
theirs = {'f1': 'v1_theirs', 'f2': 'v2', 'f3': 'v3_new'}
res = detect_merge_conflicts(base, ours, theirs)
assert res == ['f1'], f'Ожидался конфликт только в f1, получено {res}'

# 2. Одинаковое изменение в обеих ветках - нет конфликта
base = {'f': 'init'}
ours = {'f': 'same'}
theirs = {'f': 'same'}
assert detect_merge_conflicts(base, ours, theirs) == [], 'Одинаковые изменения не должны вызывать конфликт'

# 3. Создание нового файла: разное -> конфликт, одинаковое -> нет
base = {}
ours = {'new_diff': 'a', 'new_same': 'x'}
theirs = {'new_diff': 'b', 'new_same': 'x'}
res = detect_merge_conflicts(base, ours, theirs)
assert res == ['new_diff'], f'Ожидался конфликт в new_diff, получено {res}'

# 4. Удаление против изменения
base = {'f_del': 'old'}
ours = {}
theirs = {'f_del': 'edited'}
assert detect_merge_conflicts(base, ours, theirs) == ['f_del'], 'Удаление против изменения должно давать конфликт'

# 5. Обе стороны удалили файл - нет конфликта
base = {'f_del': 'old'}
assert detect_merge_conflicts(base, {}, {}) == [], 'Синхронное удаление файла не является конфликтом'

# 6. Пустые репозитории
assert detect_merge_conflicts({}, {}, {}) == [], 'Пустые репозитории не должны давать конфликтов'
